import os, pandas as pd, numpy as np; os.makedirs("data", exist_ok=True); np.random.seed(42); n=1200; dates=pd.date_range("2023-01-01", periods=n, freq="D"); comms=["Wheat","Paddy","Maize","Mustard","Apple"]; dists=["Rajouri","Poonch","Jammu","Kathua","Udhampur"]; df=pd.DataFrame({"Date":np.random.choice(dates,n), "Commodity":np.random.choice(comms,n), "District":np.random.choice(dists,n), "Rainfall_Index_mm":np.round(np.random.exponential(10.0,n),2), "Mandi_Arrival_Tonnes":np.round(np.random.uniform(10.0,150.0,n),2)}); base={"Wheat":2275,"Paddy":2183,"Maize":2090,"Mustard":5650,"Apple":7500}; df["Modal_Price"]=df.apply(lambda r: round(base[r["Commodity"]] - (r["Mandi_Arrival_Tonnes"]*1.5) + (r["Rainfall_Index_mm"]*3.2) + np.random.normal(0,45),2), axis=1); df.to_csv("data/mandi_data.csv", index=False); print("? Mandi dataset ready: data/mandi_data.csv")
